import React, { useEffect, useState } from "react";
import axios from "axios";

function QuizStudent() {
  const studentId = localStorage.getItem("user_id");

  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [score, setScore] = useState(null);

  // 🔥 Fetch Questions
  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/questions/1") // quiz_id = 1
      .then((res) => setQuestions(res.data))
      .catch((err) => console.error(err));
  }, []);

  // 🔥 Handle Option Select
  const handleChange = (qId, option) => {
    setAnswers({
      ...answers,
      [qId]: option
    });
  };

  // 🔥 Submit Quiz
  const submitQuiz = async () => {
    try {
      const res = await axios.post(
        "http://127.0.0.1:8000/submit-quiz",
        {
          quiz_id: 1,
          student_id: parseInt(studentId),
          answers: answers
        }
      );

      setScore(res.data.score);

      // 🔥 Smart Planner auto refresh trigger
      window.dispatchEvent(new Event("plannerUpdated"));

    } catch (err) {
      console.error("Quiz submit error:", err);
    }
  };

  return (
    <div>
      <h2 style={{ color: "#6a1b9a", marginBottom: "20px" }}>
        Quiz Section 🧠
      </h2>

      {questions.length === 0 ? (
        <p>Loading questions...</p>
      ) : (
        questions.map((q, index) => (
          <div key={q.id} style={card}>
            <h4>
              Q{index + 1}. {q.question}
            </h4>

            <div style={{ marginTop: "10px" }}>
              {[q.option1, q.option2, q.option3, q.option4].map(
                (opt, i) => (
                  <label key={i} style={optionStyle}>
                    <input
                      type="radio"
                      name={`question-${q.id}`}
                      value={opt}
                      onChange={() => handleChange(q.id, opt)}
                    />
                    {opt}
                  </label>
                )
              )}
            </div>
          </div>
        ))
      )}

      {/* Submit Button */}
      <button onClick={submitQuiz} style={submitBtn}>
        Submit Quiz
      </button>

      {/* Score Display */}
      {score !== null && (
        <div style={scoreBox}>
          🎯 Your Score: {score} / {questions.length}
        </div>
      )}
    </div>
  );
}

/* 🎨 Styles */

const card = {
  background: "#fff",
  padding: "15px",
  borderRadius: "12px",
  marginBottom: "15px",
  boxShadow: "0 4px 12px rgba(0,0,0,0.1)"
};

const optionStyle = {
  display: "block",
  marginBottom: "8px",
  cursor: "pointer"
};

const submitBtn = {
  marginTop: "20px",
  background: "#7b1fa2",
  color: "#fff",
  border: "none",
  padding: "12px 20px",
  borderRadius: "10px",
  cursor: "pointer",
  fontSize: "16px"
};

const scoreBox = {
  marginTop: "20px",
  padding: "15px",
  background: "#e8f5e9",
  color: "#2e7d32",
  borderRadius: "10px",
  fontWeight: "bold",
  textAlign: "center"
};

export default QuizStudent;
